// truchets list https://www.shadertoy.com/playlist/mcSSzG

#define draw(p) mix(o, vec4(0, 0, .5, 0), smoothstep(14. / r.y, .0, length(p) - .03))

#define H(p) fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453)  // hash
#define rot(a) mat2(cos(a + vec4(0, 1, 3, 0) * pi / 2.))
#define pi acos(-1.)
#define tau (2. * pi)
#define sq sqrt(3.)
#define hex vec2(1, sq)

void hexgrid(vec2 u, out vec2 p, out vec2 id) {
    vec2 a = mod(u,            hex) - hex / 2.,
         b = mod(u - hex / 2., hex) - hex / 2.;

    p = a;
    id = floor(u / hex) * 2.;

    if(dot(a, a) > dot(b, b)) {
        id = floor(u / hex - .5) * 2. + 1.;
        p = b;
    }
}



vec2 curve(vec2 q, float dir){
    q = vec2(
            atan(q.y, q.x) + dir * iTime,
            length(q)
        );

    float a = (mod(q.x * 12., tau) - pi) / 12.;

    return vec2(
               q.y * cos(a) - .288,
               q.y * sin(a)
           );
}


void mainImage(out vec4 o, vec2 u) {
    vec2 r = iResolution.xy, p, id;
    u = 2.4 * (u + u - r) / r.y + vec2(iTime) * .3 + 5.;
    o *= .0;

    hexgrid(u, p, id);

    int k = int(id.x) % 3;

    vec4 c = vec4(8, 4, 1, 0) / 12.;
    if (k == 0) o = c.xxzw;
    if (k == 1) o = c.xyzw;
    if (k == 2) o = c.xxxw;
    o *= .8;


    float dir = k == 1 ? -1. : 1.;

    p *= rot(floor(H(id + .1) * 3.) * tau / 3.);

    o = draw(curve(p + dir * vec2(.5, .288), dir));
    o = draw(curve(p - dir * vec2(.5, .288), -dir));


    o = mix(
            o, 
            vec4(1),
            smoothstep(14. / r.y, 0., 
                abs(
                    length(p + dir * vec2(.5, .288)) - .288
                ) - .1
            )/2.
        );


    o = mix(
            o, 
            vec4(1),
            smoothstep(14. / r.y, 0., 
                abs(
                    length(p - dir * vec2(.5, .288)) - .288
                ) - .1
            ) / 2.
        );






    vec2 q = p *= rot(2. * tau / 3.);
    q.x = fract(q.x * 8. - iTime * 12. / tau) - .5;
    q.x /= 8.;


    o = mix(
            o, 
            mix(
                vec4(1), 
                vec4(0, 0, 1., 0), 
                smoothstep(14. / r.y, .0, length(q) - .03)
            ), 
            smoothstep(14. / r.y, .0, length(p.y) - .1) / 2.
        );


    if(iMouse.z > 0. || mod(iTime, 12.) < 2.)
        o = pow(1. - o, vec4(4.));
}
